/**
 * **A buyer's child never reaches the public bucket, and this is the proof.**
 *
 * There are two R2 buckets (`lib/artwork/store.ts` § THE DECISION). The looks
 * bucket is **public** — a Cloudflare custom domain is attached to it — because
 * the looks' pages are shown to everybody during a preview with no watermark
 * and no account. The order-artwork bucket is **private**, with no domain,
 * because it holds artwork regenerated by hand from a photograph of one
 * family's child. A per-order picture in the public bucket would be a guessable
 * URL for somebody's baby. It is the worst thing this product could do, and it
 * is worth more than a convention.
 *
 * **Both halves are on one provider now, and that is why this file grew.**
 * While they were a Vercel Blob token and an OIDC store id, the credentials
 * were themselves part of the wall — the fourth one below used to be about
 * exactly that. One R2 token covers both buckets by the captain's decision, so
 * the only thing separating them in a signed request is the bucket name in the
 * path, and the credential is no longer any kind of guard. What replaced it is
 * two walls rather than one: the bucket *configurations* cannot be mistaken for
 * each other by the compiler, and a public bucket that is also a private bucket
 * is **refused at the environment seam** rather than served.
 *
 * So there are five walls, and this file is all five:
 *
 * 1. **The types.** `PublicArtworkStore` and `PrivateArtworkStore` are mutually
 *    unassignable, with no cast and no widening helper anywhere in the
 *    repository. `test/no-order-asset-in-the-public-store.ts` is a file of calls
 *    that must not compile; `tsc` reports an unused `@ts-expect-error` as an
 *    error, so `npm run lint` is the assertion. This file checks that the file
 *    is still there and still says what it says — a deleted fixture would
 *    otherwise be a silently removed gate.
 *
 * 2. **The keys.** The public store is keyed by `isReleaseSet`, which no order
 *    reference satisfies, so a key that arrived through a `string` the compiler
 *    cannot see into is refused at runtime too.
 *
 * 3. **The URLs.** The private store records none. There is nothing in anything
 *    it returns for an `<img src>` to be handed, even by accident.
 *
 * 4. **The configurations.** `LooksBucket` and `OrderArtworkBucket` are
 *    mutually unassignable, and `publicBase` — the field that turns bytes into
 *    a URL — does not exist at all on the private one. So neither store can be
 *    built against the other's bucket, and a private store with URLs is not a
 *    thing the module can be asked for.
 *
 * 5. **The bucket names.** This is the one that would be silent. One token
 *    covers both buckets, so the same bucket name pasted into the public row
 *    and a private row would authenticate perfectly and publish every order
 *    record in it. `looksBucketIn` refuses that collision, names the row that
 *    collided, and falls back to the local directory — because a shop with no
 *    artwork is a state this repository is built to be fine in, and a CDN
 *    serving a customer's child is not.
 */

import { readFileSync, readdirSync, statSync } from "node:fs";
import path from "node:path";
import { describe, expect, it } from "vitest";
import { PNG } from "pngjs";
import {
  ACCESS_KEY_VAR,
  ACCOUNT_VAR,
  LOOKS_BUCKET_VAR,
  ORDER_ARTWORK_BUCKET_VAR,
  PRIVATE_BUCKET_VARS,
  PUBLIC_BASE_VAR,
  SECRET_KEY_VAR,
  looksBucketIn,
  looksR2Store,
  orderArtworkBucketIn,
  orderArtworkR2Store,
  publicBucketCollision,
} from "../lib/artwork/r2";
import type { ObjectApi } from "../lib/artwork/object-store";
import {
  ARTWORK_DIR_VAR,
  NotAnOrderReference,
  artworkStoreFromEnv,
  localOrderStore,
} from "../lib/artwork/store";
import {
  GHOSTS_SET,
  RELEASE_ARTWORK_DIR_VAR,
  TILES_SET,
  localReleaseStore,
  lookSet,
  releaseStoreFromEnv,
} from "../lib/artwork/release";

const ROOT = process.cwd();
const REF = "BK-7QX4RMT";
const NOW = new Date("2026-11-10T09:00:00.000Z");

/**
 * One Cloudflare account, one token. The values are long enough to be real:
 * `lib/env.ts` § `isSet` reads anything under eight characters as a row
 * somebody left behind, which is a rule worth tripping over here rather than
 * on a deploy.
 */
const ACCOUNT = {
  accountId: "accountsekrit",
  accessKeyId: "keyidsekrit",
  secretAccessKey: "secretsekrit",
};
const LOOKS = {
  for: "looks",
  ...ACCOUNT,
  bucket: "onelittlebook-looks",
  publicBase: "https://art.onelittlebook.test",
} as const;
const ORDERS = { for: "order-artwork", ...ACCOUNT, bucket: "onelittlebook-orders" } as const;

/** The environment that reaches both of them. */
const BOTH = {
  [ACCOUNT_VAR]: ACCOUNT.accountId,
  [ACCESS_KEY_VAR]: ACCOUNT.accessKeyId,
  [SECRET_KEY_VAR]: ACCOUNT.secretAccessKey,
  [LOOKS_BUCKET_VAR]: LOOKS.bucket,
  [PUBLIC_BASE_VAR]: LOOKS.publicBase,
  [ORDER_ARTWORK_BUCKET_VAR]: ORDERS.bucket,
};

/** The in-memory bucket, so nothing here needs a network or a credential. */
function bucket(): { api: ObjectApi; puts: string[] } {
  const files = new Map<string, Uint8Array>();
  const puts: string[] = [];
  return {
    puts,
    api: {
      async put(pathname, bytes) {
        puts.push(pathname);
        files.set(pathname, bytes);
        return { url: `${LOOKS.publicBase}/${pathname}` };
      },
      async has(pathname) {
        return files.has(pathname);
      },
      async pathnames(prefix) {
        return [...files.keys()].filter((key) => key.startsWith(prefix));
      },
      async bytes(pathname) {
        return files.get(pathname) ?? null;
      },
    },
  };
}

/** A tiny picture standing in for a page of somebody's child. */
function picture(): Uint8Array {
  const png = new PNG({ width: 8, height: 8 });
  png.data.fill(90);
  return new Uint8Array(PNG.sync.write(png, { colorType: 2, inputHasAlpha: true, bitDepth: 8 }));
}

// ---------------------------------------------------------------------------
// 1. The types
// ---------------------------------------------------------------------------

describe("the compile-time wall", () => {
  const FIXTURE = path.join(ROOT, "test", "no-order-asset-in-the-public-store.ts");
  const fixture = readFileSync(FIXTURE, "utf8");

  it("is a file of calls that must not compile, and it is still here", () => {
    // A number rather than "some", because the way this gate decays is one
    // directive at a time. It went from eight to fourteen when both halves
    // landed on one provider — the configurations and the screen store are the
    // six that arrived with it.
    const directives = fixture.match(/@ts-expect-error/g) ?? [];
    expect(directives.length).toBeGreaterThanOrEqual(14);
  });

  it("covers both directions and the untagged store as well", () => {
    expect(fixture).toContain("keepPerOrderArtwork(looks)");
    expect(fixture).toContain("keepReleasedArtwork(orders)");
    expect(fixture).toContain("keepPerOrderArtwork(untagged)");
    expect(fixture).toContain("keepReleasedArtwork(untagged)");
  });

  it("covers the two bucket configurations, which is the wall one provider needs", () => {
    // Each store built against the other's bucket, in both directions, plus
    // the attempt to put a public base on the private configuration at all.
    expect(fixture).toContain("looksR2Store(ORDERS_BUCKET)");
    expect(fixture).toContain("orderArtworkR2Store(LOOKS_BUCKET)");
    expect(fixture).toContain("publicBase:");
    expect(fixture).toContain("objectScreenStore(");
  });

  it("is checked by the typechecker the gate already runs", () => {
    // `tsconfig.json` includes every `.ts` in the project and CI runs
    // `npm run lint`, which is `tsc --noEmit`. If that ever stops covering
    // `test/`, this gate stops existing.
    const tsconfig = JSON.parse(readFileSync(path.join(ROOT, "tsconfig.json"), "utf8"));
    expect(tsconfig.include).toContain("**/*.ts");
    const pkg = JSON.parse(readFileSync(path.join(ROOT, "package.json"), "utf8"));
    expect(pkg.scripts.lint).toContain("tsc");
  });

  it("is not collected by the test runner, so it never has to pass at runtime", () => {
    const config = readFileSync(path.join(ROOT, "vitest.config.mts"), "utf8");
    expect(config).toContain("test/**/*.test.{ts,tsx}");
    expect(path.basename(FIXTURE)).not.toMatch(/\.test\./);
  });
});

// ---------------------------------------------------------------------------
// 2. The keys
// ---------------------------------------------------------------------------

describe("the public bucket refuses an order's key", () => {
  it("will not write per-order artwork, even asked through a plain string", async () => {
    const store = looksR2Store(LOOKS, bucket().api);
    await expect(store.put(REF, [{ pageId: "page-006", bytes: picture() }], NOW)).rejects.toThrow(
      NotAnOrderReference,
    );
  });

  it("will not read one back either, so nothing could be fetched by reference", async () => {
    const store = looksR2Store(LOOKS, bucket().api);
    await expect(store.versions(REF)).rejects.toThrow(NotAnOrderReference);
    await expect(store.read(REF, 1, "page-006")).rejects.toThrow(NotAnOrderReference);
  });

  it("refuses the same key on the filesystem, so the two cannot disagree", async () => {
    const store = localReleaseStore("/tmp/olb-never-written");
    await expect(store.put(REF, [{ pageId: "page-006", bytes: picture() }], NOW)).rejects.toThrow(
      NotAnOrderReference,
    );
  });

  it("writes nothing to the bucket when it refuses", async () => {
    const b = bucket();
    const store = looksR2Store(LOOKS, b.api);
    await store.put(TILES_SET, [{ pageId: "tile-ada", bytes: picture() }], NOW).catch(() => {});
    const before = b.puts.length;
    await store.put(REF, [{ pageId: "page-006", bytes: picture() }], NOW).catch(() => {});
    expect(b.puts.length).toBe(before);
  });

  it("and the private store refuses a release set, which is the same wall", async () => {
    const store = orderArtworkR2Store(ORDERS, bucket().api);
    for (const set of [TILES_SET, GHOSTS_SET, lookSet("girl-02")]) {
      await expect(store.put(set, [{ pageId: "page-002", bytes: picture() }], NOW)).rejects.toThrow(
        NotAnOrderReference,
      );
    }
  });
});

// ---------------------------------------------------------------------------
// 3. The URLs
// ---------------------------------------------------------------------------

describe("the private bucket publishes no address", () => {
  it("records no url for a page, where the public store records one", async () => {
    const pages = [{ pageId: "page-006", bytes: picture() }];
    const privately = await orderArtworkR2Store(ORDERS, bucket().api).put(REF, pages, NOW);
    const publicly = await looksR2Store(LOOKS, bucket().api).put(TILES_SET, [
      { pageId: "tile-ada", bytes: picture() },
    ], NOW);

    expect(privately.pages[0].url).toBeUndefined();
    // The paired half: the same code path, on the public bucket's store, does
    // produce one — so the assertion above is about which bucket this is and
    // not about a feature that is broken for everybody.
    expect(publicly.pages[0].url).toMatch(/^https:\/\//);
  });

  it("holds nothing that looks like a url anywhere in its record", async () => {
    const version = await orderArtworkR2Store(ORDERS, bucket().api).put(
      REF,
      [{ pageId: "page-006", bytes: picture() }],
      NOW,
    );
    expect(JSON.stringify(version)).not.toMatch(/https?:\/\//);
  });

  it("is read by a route behind the admin guard and never by a url", () => {
    // The route that serves per-order artwork existed before the bucket did,
    // and `test/admin-guard.test.ts` asserts that everything under
    // `app/api/admin/` goes through the guard. This checks only that the
    // artwork route is still one of those files.
    const route = path.join(ROOT, "app", "api", "admin", "artwork", "[ref]", "route.ts");
    expect(statSync(route).isFile()).toBe(true);
    expect(readFileSync(route, "utf8")).toContain("allowedFor");
  });
});

// ---------------------------------------------------------------------------
// 4. The configurations
// ---------------------------------------------------------------------------

describe("the two bucket configurations", () => {
  it("each build only their own store, and the env reader keeps them apart", () => {
    // The compiler's half is the fixture above; this is that the two readers
    // answer with the bucket they are for and never the other one.
    expect(looksBucketIn(BOTH)).toEqual(LOOKS);
    expect(orderArtworkBucketIn(BOTH)).toEqual(ORDERS);
  });

  it("read two different rows, so one value cannot serve both", () => {
    // The paired negative of the case above: drop the public row and the
    // public reader says no while the private one still answers. A single
    // bucket variable shared between them would make both of these pass with
    // the same value, which is the mistake the fifth wall is about.
    const noLooks = { ...BOTH, [LOOKS_BUCKET_VAR]: "" };
    expect(looksBucketIn(noLooks)).toBeNull();
    expect(orderArtworkBucketIn(noLooks)).toEqual(ORDERS);

    const noOrders = { ...BOTH, [ORDER_ARTWORK_BUCKET_VAR]: "" };
    expect(orderArtworkBucketIn(noOrders)).toBeNull();
    expect(looksBucketIn(noOrders)).toEqual(LOOKS);
  });

  it("has nowhere on the private side for the thing that makes a URL", () => {
    // The runtime half of `publicBase` not existing on `OrderArtworkBucket`:
    // the store it builds writes no url on anything, so there is nothing for
    // an `<img src>` to be handed even by accident.
    const config = orderArtworkBucketIn(BOTH)!;
    expect("publicBase" in config).toBe(false);
    expect(Object.values(config)).not.toContain(LOOKS.publicBase);
  });
});

// ---------------------------------------------------------------------------
// 5. The bucket names
// ---------------------------------------------------------------------------

describe("a public bucket that is also a private bucket is refused", () => {
  /** Every private row, each tried in turn: neither may ever be the public one. */
  it("is refused for every private row there is, not just the one somebody thought of", () => {
    expect(PRIVATE_BUCKET_VARS.length).toBeGreaterThanOrEqual(2);
    for (const row of PRIVATE_BUCKET_VARS) {
      const clash = { ...BOTH, [row]: LOOKS.bucket };
      expect(publicBucketCollision(clash), row).toBe(row);
      // And the refusal is the store it builds, not merely an advisory.
      expect(looksBucketIn(clash), row).toBeNull();
    }
  });

  it("falls back to the local directory and says which row collided", () => {
    const store = releaseStoreFromEnv({
      ...BOTH,
      "R2_BUCKET": LOOKS.bucket,
      [RELEASE_ARTWORK_DIR_VAR]: "/tmp/olb-looks-local",
    });
    expect(store.holds).toBe("released");
    expect(store.describe).toContain("/tmp/olb-looks-local");
    expect(store.describe).toContain("R2_BUCKET");
    // The reason, in the sentence, because the fix is not obvious from the
    // symptom: a custom domain is a bucket-level thing.
    expect(store.describe).toContain("not to a prefix");
    expect(store.describe).not.toContain(LOOKS.publicBase);
  });

  it("is not refused when the two private rows are the same bucket, which is allowed", () => {
    // The paired positive. Both private rows may legitimately name one bucket
    // — their prefixes do not collide and neither has a domain — so the check
    // has to be about public-versus-private and not about uniqueness.
    const shared = { ...BOTH, "R2_BUCKET": ORDERS.bucket };
    expect(publicBucketCollision(shared)).toBeNull();
    expect(looksBucketIn(shared)).toEqual(LOOKS);
  });

  it("says nothing about a collision nobody could have, so the check is not noise", () => {
    expect(publicBucketCollision({})).toBeNull();
    expect(publicBucketCollision({ [LOOKS_BUCKET_VAR]: "" })).toBeNull();
  });

  it("names the two bucket rows in two different modules, so they cannot be folded into one", () => {
    // The *strings* — the only way to read a variable is to name it.
    // `R2_LOOKS_BUCKET` is read where the public decision is made and
    // `R2_BUCKET` where the orders are, and the day one file reads both is
    // the day one value could serve both.
    expect(filesNaming(`"${LOOKS_BUCKET_VAR}"`, [path.join(ROOT, "lib")])).toEqual([
      path.join("lib", "artwork", "r2.ts"),
    ]);
    expect(filesNaming('"R2_BUCKET"', [path.join(ROOT, "lib")])).toEqual([
      path.join("lib", "artwork", "r2.ts"),
      path.join("lib", "orders", "config.ts"),
      path.join("lib", "orders", "store.ts"),
    ]);
  });
});

// ---------------------------------------------------------------------------
// The per-order store this environment builds
// ---------------------------------------------------------------------------

describe("the per-order store", () => {
  it("is the private bucket once there is a credential for it", () => {
    const store = artworkStoreFromEnv(BOTH);
    expect(store.holds).toBe("per-order");
    expect(store.describe).toContain(ORDERS.bucket);
    expect(store.describe).toContain("no public URLs");
    // Never the public bucket, and never a credential.
    expect(store.describe).not.toContain(LOOKS.bucket);
    expect(store.describe).not.toContain(ACCOUNT.secretAccessKey);
  });

  it("is the filesystem with nothing configured, which is a fresh clone", () => {
    const store = artworkStoreFromEnv({ [ARTWORK_DIR_VAR]: "/tmp/olb-orders-local" });
    expect(store.holds).toBe("per-order");
    expect(store.describe).toContain("/tmp/olb-orders-local");
    expect(store.describe).not.toContain("R2");
  });

  it("is the filesystem AND says which rows are empty when it is half-configured", () => {
    // The state that looks configured from a dashboard and is not: a bucket
    // named with no key to reach it. Silent fallback here would accept an
    // upload in production and lose it on the next deploy.
    const store = artworkStoreFromEnv({
      [ORDER_ARTWORK_BUCKET_VAR]: ORDERS.bucket,
      [ARTWORK_DIR_VAR]: "/tmp/olb-orders-local",
    });
    expect(store.describe).toContain("/tmp/olb-orders-local");
    expect(store.describe).toContain(ACCOUNT_VAR);
    expect(store.describe).toContain(ACCESS_KEY_VAR);
    expect(store.describe).toContain(SECRET_KEY_VAR);
  });

  it("is reachable from nothing that writes the looks' artwork", () => {
    // Read off disk rather than trusted: `lib/artwork/r2.ts` exports both
    // constructors, so the check that matters is which of them the per-order
    // modules name.
    for (const file of [
      path.join("lib", "book", "order-upload.ts"),
      path.join("lib", "book", "order-art.ts"),
      path.join("lib", "orders", "store.ts"),
      path.join("app", "api", "admin", "artwork", "[ref]", "route.ts"),
      path.join("app", "api", "admin", "pages", "[ref]", "route.ts"),
    ]) {
      const source = readFileSync(path.join(ROOT, file), "utf8");
      expect(source, `${file} names the public store`).not.toContain("looksR2Store");
      expect(source, `${file} names the public bucket`).not.toContain(LOOKS_BUCKET_VAR);
      expect(source, `${file} names the public domain`).not.toContain(PUBLIC_BASE_VAR);
    }
  });
});

describe("the local per-order store", () => {
  it("is tagged for per-order artwork and keyed by an order reference", async () => {
    const store = localOrderStore("/tmp/olb-never-written-either");
    expect(store.holds).toBe("per-order");
    await expect(store.put(TILES_SET, [{ pageId: "tile-ada", bytes: picture() }], NOW)).rejects.toThrow(
      NotAnOrderReference,
    );
  });
});

/** Every file under these roots whose source names a variable, repo-relative. */
function filesNaming(name: string, roots: string[]): string[] {
  const found: string[] = [];
  const walk = (dir: string) => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const full = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        if (entry.name === "node_modules" || entry.name.startsWith(".")) continue;
        walk(full);
      } else if (/\.(ts|tsx)$/.test(entry.name) && readFileSync(full, "utf8").includes(name)) {
        found.push(path.relative(ROOT, full));
      }
    }
  };
  for (const root of roots) walk(root);
  return found.sort();
}
